11:     public async Task<IReadOnlyList<PendingCheck>> GetPendingChecksAsync(CancellationToken ct = default)
12:     {
13:         // CHECKS-API: Liste aller Check-Evaluations mit Status 'pending'
14:         // Endpoint variiert je nach ADO Server Version; hier der typische Pfad für Azure DevOps Server 2022.x:
15:         var url = $"_apis/pipelines/checks/check-evaluations?api-version={ApiVersion}&statusFilter=pending";
16: 
17:         using var response = await httpClient.GetAsync(url, ct);
