25:         {
26:             checks.Add(new PendingCheck(
27:                 Id: element.GetProperty("id").GetInt32(),
28:                 EnvironmentName: element.GetProperty("environment").GetProperty("name").GetString() ?? string.Empty,
29:                 ProjectName: element.GetProperty("environment").GetProperty("project").GetProperty("name").GetString() ?? string.Empty,
30:                 PipelineName: element.TryGetProperty("pipeline", out var p) ? p.GetProperty("name").GetString() ?? string.Empty : string.Empty,
31:                 RunId: element.TryGetProperty("pipelineRun", out var r) && r.TryGetProperty("id", out var rid) ? rid.GetInt32() : 0,
32:                 RepositoryId: element.TryGetProperty("resource", out var res) && res.TryGetProperty("repository", out var repo) && repo.TryGetProperty("id", out var rid2) ? rid2.GetString() ?? string.Empty : string.Empty,
33:                 SourceCommitId: element.TryGetProperty("resource", out var res2) && res2.TryGetProperty("repository", out var repo2) && repo2.TryGetProperty("version", out var ver) ? ver.GetString() ?? string.Empty : string.Empty,
34:                 SourceBranch: element.TryGetProperty("resource", out var res3) && res3.TryGetProperty("repository", out var repo3) && repo3.TryGetProperty("branch", out var br) ? br.GetString() : null,
35:                 DefinitionName: element.TryGetProperty("definition", out var def) ? def.GetProperty("name").GetString() : null
36:             ));
37:         }
38: 
39:         return checks;
40:     }
