42:     public async Task<PullRequestInfo?> GetPullRequestForCommitAsync(
43:         string projectName,
44:         string repositoryId,
45:         string commitId,
46:         CancellationToken ct = default)
47:     {
48:         // PRs suchen, die den Commit enthalten (lastMergeTargetCommit / lastMergeSourceCommit)
49:         var url = $"_apis/git/repositories/{repositoryId}/pullrequests?api-version={ApiVersion}&searchCriteria.status=active,completed&searchCriteria.repositoryId={repositoryId}";
50: 
51:         using var response = await httpClient.GetAsync(url, ct);
52:         if (!response.IsSuccessStatusCode)
53:         {
54:             logger.LogWarning("Konnte Pull-Requests nicht laden (Status {StatusCode})", response.StatusCode);
55:             return null;
56:         }
57: 
58:         var json = await response.Content.ReadAsStringAsync(ct);
59:         var doc = JsonDocument.Parse(json);
60: 
61:         foreach (var pr in doc.RootElement.GetProperty("value").EnumerateArray())
62:         {
63:             var prId = pr.GetProperty("pullRequestId").GetInt32();
64:             var title = pr.GetProperty("title").GetString() ?? string.Empty;
65:             var creator = pr.GetProperty("createdBy");
66:             var creatorDisplay = creator.TryGetProperty("displayName", out var dn) ? dn.GetString() ?? string.Empty : string.Empty;
67:             var creatorUnique = creator.TryGetProperty("uniqueName", out var un) ? un.GetString() ?? string.Empty : string.Empty;
68:             var sourceBranch = pr.GetProperty("sourceRefName").GetString() ?? string.Empty;
69:             var targetBranch = pr.GetProperty("targetRefName").GetString() ?? string.Empty;
70: 
71:             // Geänderte Dateien des PR abfragen
72:             var changedFiles = await GetChangedFilesAsync(repositoryId, prId, ct);
73: 
74:             // Dockerfile-Diffs für Digest-Prüfung abfragen
75:             var dockerfileDiffs = await GetDockerfileDiffsAsync(repositoryId, prId, ct);
76: 
77:             // Prüfung: Enthält der PR den Ziel-Commit als Merge-Ziel?
78:             if (pr.TryGetProperty("lastMergeTargetCommit", out var targetCommit) &&
79:                 targetCommit.TryGetProperty("commitId", out var tcid) &&
80:                 tcid.GetString() == commitId)
81:             {
82:                 return new PullRequestInfo(
83:                     Id: prId,
84:                     Title: title,
85:                     CreatorDisplayName: creatorDisplay,
86:                     CreatorUniqueName: creatorUnique,
87:                     SourceBranch: sourceBranch,
88:                     TargetBranch: targetBranch,
89:                     ChangedFilePaths: changedFiles,
90:                     DockerfileDiffs: dockerfileDiffs);
91:             }
92:         }
93: 
94:         return null;
95:     }
