97:     public async Task ApproveCheckAsync(int checkEvaluationId, CancellationToken ct = default)
98:     {
99:         var url = $"_apis/pipelines/checks/check-evaluations/{checkEvaluationId}?api-version={ApiVersion}";
100:         var body = JsonSerializer.Serialize(new { status = "approved" }, JsonOptions);
101:         using var content = new StringContent(body, System.Text.Encoding.UTF8, "application/json");
102: 
103:         using var response = await httpClient.PatchAsync(url, content, ct);
104:         response.EnsureSuccessStatusCode();
105:         logger.LogInformation("CheckEvaluation {Id} erfolgreich genehmigt (Status {StatusCode})", checkEvaluationId, response.StatusCode);
106:     }
