108:     private async Task<IReadOnlyList<string>> GetChangedFilesAsync(string repositoryId, int pullRequestId, CancellationToken ct)
109:     {
110:         var url = $"_apis/git/repositories/{repositoryId}/pullrequests/{pullRequestId}/diffs/commits?api-version={ApiVersion}";
111: 
112:         using var response = await httpClient.GetAsync(url, ct);
113:         if (!response.IsSuccessStatusCode)
114:             return Array.Empty<string>();
115: 
116:         var json = await response.Content.ReadAsStringAsync(ct);
117:         var doc = JsonDocument.Parse(json);
118: 
119:         var files = new List<string>();
120:         foreach (var change in doc.RootElement.GetProperty("changes").EnumerateArray())
121:         {
122:             if (change.TryGetProperty("item", out var item) && item.TryGetProperty("path", out var path))
123:                 files.Add(path.GetString() ?? string.Empty);
124:         }
125: 
126:         return files;
127:     }
