    LogLevel.Information, 1007, "{Count} ausstehende Check-Evaluations gefunden");

private static readonly Action<ILogger, int, string, Exception?> _logProcessingError = LoggerMessage.Define(
    LogLevel.Error, 1008, "Fehler bei der Verarbeitung von CheckEvaluation {0} in Environment {1}");

