using AutoApprover.Worker.Models;
using AutoApprover.Worker.Services;

namespace AutoApprover.Worker;

internal sealed class ApprovalWorker(
    IAdoApiClient adoApiClient,
    IDecisionEngine decisionEngine,
    IAuditRepository auditRepository,
    ITeamsNotifier teamsNotifier,
    IConfiguration configuration,
    ILogger<ApprovalWorker> logger) : BackgroundService
{
    private static readonly Action<ILogger, Exception?> _logOneOffMode = LoggerMessage.Define(
        LogLevel.Information, 1001, "Auto-Approver Worker im One-Off-Modus (einzelner Durchlauf)");

    private static readonly Action<ILogger, Exception?> _logOneOffCompleted = LoggerMessage.Define(
        LogLevel.Information, 1002, "Auto-Approver Worker One-Off abgeschlossen.");

    private static readonly Action<ILogger, double, Exception?> _logStarted = LoggerMessage.Define(
        LogLevel.Information, 1003, "Auto-Approver Worker gestartet. Polling-Intervall: {0}s");

    private static readonly Action<ILogger, Exception?> _logPollingError = LoggerMessage.Define(
        LogLevel.Error, 1004, "Unerwarteter Fehler im Polling-Zyklus");

    private static readonly Action<ILogger, Exception?> _logEnded = LoggerMessage.Define(
        LogLevel.Information, 1005, "Auto-Approver Worker beendet.");

    private static readonly Action<ILogger, Exception?> _logChecking = LoggerMessage.Define(
        LogLevel.Debug, 1006, "Pruefe auf ausstehende Environment-Checks ...");

    private static readonly Action<ILogger, int, Exception?> _logPendingCount = LoggerMessage.Define(
        LogLevel.Information, 1007, "{0} ausstehende Check-Evaluations gefunden");

    private static readonly Action<ILogger, int, string, Exception?> _logProcessingError = LoggerMessage.Define(
        LogLevel.Error, 1008, "Fehler bei der Verarbeitung von CheckEvaluation {0} in Environment {1}");

    private static readonly Action<ILogger, int, string, string, Exception?> _logProcessingCheck = LoggerMessage.Define(
        LogLevel.Information, 1009, "Verarbeite CheckEvaluation {0} (Environment: {1}, Pipeline: {2})");

    private static readonly Action<ILogger, int, string, Exception?> _logCheckApproved = LoggerMessage.Define(
        LogLevel.Information, 1010, "CheckEvaluation {0} automatisch genehmigt. Grund: {1}");

    private static readonly Action<ILogger, int, string, Exception?> _logCheckSkipped = LoggerMessage.Define(
        LogLevel.Information, 1011, "CheckEvaluation {0} uebersprungen. Grund: {1}");

    private readonly TimeSpan _pollingInterval = TimeSpan.FromSeconds(
        configuration.GetValue<int>("AdopSettings:PollingIntervalSeconds", 60));

    private readonly bool _runOnce = configuration.GetValue<bool>("AdopSettings:RunOnce",
        Environment.GetEnvironmentVariable("AUTOAPPROVE_ONCE") is { } envVar &&
        bool.TryParse(envVar, out var parsed) && parsed);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        if (_runOnce)
        {
            _logOneOffMode(logger, null);
            await ProcessPendingChecksAsync(stoppingToken).ConfigureAwait(false);
            _logOneOffCompleted(logger, null);
            return;
        }

        _logStarted(logger, _pollingInterval.TotalSeconds, null);

        while (!stoppingToken.IsCancellationRequested)
        {
#pragma warning disable CA1031 // Ein Worker-Polling-Loop faengt bewusst alle Ausnahme ab, um den Loop am Laufen zu halten
            try
            {
                await ProcessPendingChecksAsync(stoppingToken).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                _logPollingError(logger, ex);
            }
#pragma warning restore CA1031

            await Task.Delay(_pollingInterval, stoppingToken).ConfigureAwait(false);
        }

        _logEnded(logger, null);
    }

    private async Task ProcessPendingChecksAsync(CancellationToken ct)
    {
        _logChecking(logger, null);

        var pendingChecks = await adoApiClient.GetPendingChecksAsync(ct).ConfigureAwait(false);
        _logPendingCount(logger, pendingChecks.Count, null);

        foreach (var check in pendingChecks)
        {
            if (ct.IsCancellationRequested)
            {
                break;
            }

            try
            {
                await ProcessCheckAsync(check, ct).ConfigureAwait(false);
            }
#pragma warning disable CA1031 // Pro-Check-Fehler faengt bewusst alle Ausnahme ab, damit einzelne Checks den Loop nicht abbrechen
            catch (Exception ex)
            {
                _logProcessingError(logger, check.Id, check.EnvironmentName, ex);
            }
#pragma warning restore CA1031
        }
    }

    private async Task ProcessCheckAsync(PendingCheck check, CancellationToken ct)
    {
        _logProcessingCheck(logger, check.Id, check.EnvironmentName, check.PipelineName, null);

        // 1. PR / Commit auflösen, um den Ersteller und die geänderten Dateien zu prüfen
        var prInfo = await adoApiClient.GetPullRequestForCommitAsync(
            check.ProjectName,
            check.RepositoryId,
            check.SourceCommitId,
            ct).ConfigureAwait(false);

        // 2. Entscheidung treffen
        var decision = decisionEngine.Evaluate(check, prInfo);

        // 3. Ausführen oder überspringen
        if (decision.ShouldApprove)
        {
            await adoApiClient.ApproveCheckAsync(check.Id, ct).ConfigureAwait(false);
            _logCheckApproved(logger, check.Id, decision.Reason, null);
        }
        else
        {
            _logCheckSkipped(logger, check.Id, decision.Reason, null);
        }

        // 4. Audit-Log in PostgreSQL
        await auditRepository.WriteAsync(decision with
        {
            RunId = check.RunId,
            CommitId = check.SourceCommitId,
            EnvironmentName = check.EnvironmentName,
            ProjectName = check.ProjectName,
            PipelineName = check.PipelineName,
            Decision = decision.ShouldApprove ? "approved" : "skipped",
            Reason = decision.Reason,
            ApprovedAt = decision.ShouldApprove ? DateTimeOffset.UtcNow : null
        }, ct).ConfigureAwait(false);

        // 5. Teams-Benachrichtigung
        await teamsNotifier.NotifyAsync(decision).ConfigureAwait(false);
    }
}

